package com.customfolders.app;
import android.content.*;import android.graphics.*;import android.graphics.drawable.*;import android.view.*;import android.widget.*;
public final class Ui{
 private Ui(){} public static int dp(Context c,float v){return(int)(v*c.getResources().getDisplayMetrics().density+.5f);} public static GradientDrawable round(Context c,int color,float r){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(c,r));return d;} public static TextView text(Context c,String s,float sp,int color){TextView v=new TextView(c);v.setText(s);v.setTextSize(sp);v.setTextColor(color);return v;} public static Button button(Context c,String s,boolean primary){Button b=new Button(c);b.setText(s);b.setAllCaps(false);b.setTextSize(14);b.setTextColor(primary?Color.WHITE:ThemeUtils.text(c));b.setBackground(round(c,primary?ThemeUtils.accent(c):ThemeUtils.surface(c),14));b.setPadding(dp(c,12),0,dp(c,12),0);return b;} public static EditText input(Context c,String hint){EditText e=new EditText(c);e.setHint(hint);e.setTextColor(ThemeUtils.text(c));e.setHintTextColor(ThemeUtils.sub(c));e.setTextSize(15);e.setPadding(dp(c,12),dp(c,10),dp(c,12),dp(c,10));GradientDrawable d=round(c,ThemeUtils.surface(c),14);d.setStroke(dp(c,1),ThemeUtils.line(c));e.setBackground(d);return e;} public static LinearLayout card(Context c){LinearLayout l=new LinearLayout(c);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(dp(c,14),dp(c,14),dp(c,14),dp(c,14));l.setBackground(round(c,ThemeUtils.surface(c),18));l.setElevation(dp(c,1));return l;} public static LinearLayout.LayoutParams mp(Context c){return new LinearLayout.LayoutParams(-1,-2);} public static void margins(LinearLayout.LayoutParams p,Context c,int l,int t,int r,int b){p.setMargins(dp(c,l),dp(c,t),dp(c,r),dp(c,b));}
}
